/* INITIALIZE EMAILJS */
    /* SECURITY NOTE: This Public Key is meant to be visible in client-side code — that's
       how EmailJS works. But by default anyone who copies it can send email through your
       account from any website. Go to EmailJS Dashboard → Account → Security and add this
       site's exact domain under "Allowed Origins" so the key only works when called from
       your own site, and check the plan's monthly send limit. */
    /* CRITICAL FIX: everything below this line (theme toggle, language switch, CV
       download, mobile menu, scroll animations) lives in this same <script> block.
       If the EmailJS CDN script fails to load for any reason (slow connection,
       ad-blocker, network restriction), emailjs.init() throws and JavaScript stops
       executing the rest of the file — silently breaking every other feature on
       the page, not just the contact form. Wrapping it in try/catch contains the
       failure so the rest of the site keeps working even if EmailJS doesn't load. */
    try {
      emailjs.init("AkkkGCfQxSsMjQbm3");
    } catch (e) {
      console.warn("EmailJS failed to initialize — contact form will be unavailable, but the rest of the site still works.", e);
    }

    /* ADD JS-ANIM CLASS FOR SCROLL ANIMATIONS */
    document.documentElement.classList.add('js-anim');

    /* PARTICLES */
    (function () {
      var c = document.getElementById('pts');
      for (var i = 0; i < 16; i++) {
        var p = document.createElement('div');
        p.className = 'pt';
        var s = 1 + Math.random() * 2.5;
        p.style.cssText = 'left:' + Math.random() * 100 + '%;width:' + s + 'px;height:' + s + 'px;animation-duration:' + (9 + Math.random() * 12) + 's;animation-delay:' + (Math.random() * 10) + 's';
        c.appendChild(p);
      }
    })();

    /* SCROLL REVEAL */
    var obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) { if (e.isIntersecting) e.target.classList.add('show') });
    }, { threshold: 0.1, rootMargin: '0px 0px -30px 0px' });
    document.querySelectorAll('.rv,.rv-l,.rv-r').forEach(function (el) { obs.observe(el) });
    /* Show hero elements immediately since they're in viewport on load */
    setTimeout(function () {
      document.querySelectorAll('#hero .rv,#hero .rv-l,#hero .rv-r').forEach(function (el, i) {
        setTimeout(function () { el.classList.add('show'); }, i * 100);
      });
    }, 50);

    /* NAV ACTIVE */
    var secs = document.querySelectorAll('section[id]');
    var alinks = document.querySelectorAll('.nav-links a');
    window.addEventListener('scroll', function () {
      var cur = '';
      secs.forEach(function (s) { if (window.scrollY >= s.offsetTop - 100) cur = s.id });
      alinks.forEach(function (a) { a.style.color = a.getAttribute('href') === '#' + cur ? 'var(--gold)' : '' });
    }, { passive: true });

    /* MOBILE MENU */
    var mobOpen = false;
    function toggleMob() {
      mobOpen = !mobOpen;
      document.getElementById('ham').classList.toggle('open', mobOpen);
      document.getElementById('mobnav').classList.toggle('open', mobOpen);
      document.body.style.overflow = mobOpen ? 'hidden' : '';
    }
    function closeMob() {
      mobOpen = false;
      document.getElementById('ham').classList.remove('open');
      document.getElementById('mobnav').classList.remove('open');
      document.body.style.overflow = '';
    }

    /* THEME */
    var isDark = true;
    function swapTheme() {
      isDark = !isDark;
      document.documentElement.setAttribute('data-theme', isDark ? 'dark' : 'light');
      document.getElementById('dbtn').textContent = isDark ? '☀ Light' : '🌙 Dark';
    }

    /* LANGUAGE */
    var isAr = false;
    function swapLang() {
      isAr = !isAr;
      document.documentElement.setAttribute('lang', isAr ? 'ar' : 'en');
      document.documentElement.setAttribute('dir', isAr ? 'rtl' : 'ltr');
      document.getElementById('lbtn').textContent = isAr ? 'EN' : 'AR';
      document.querySelectorAll('[data-en]').forEach(function (el) {
        var t = isAr ? el.getAttribute('data-ar') : el.getAttribute('data-en');
        if (t) el.textContent = t;
      });
      document.querySelectorAll('[data-ph-en]').forEach(function (el) {
        el.placeholder = isAr ? (el.getAttribute('data-ph-ar') || '') : (el.getAttribute('data-ph-en') || '');
      });
    }

    /* ELEGANT CURSOR EFFECT (Desktop Only) */
    (function () {
      if (window.matchMedia('(hover: none)').matches) return; // Exit if touch device
      var dot = document.createElement('div');
      var ring = document.createElement('div');
      dot.style.cssText = 'position:fixed;width:6px;height:6px;background:#C9A84C;border-radius:50%;pointer-events:none;z-index:9999;transform:translate(-50%,-50%);will-change:left,top;transition:opacity .3s;';
      ring.style.cssText = 'position:fixed;width:28px;height:28px;border:1.5px solid rgba(201,168,76,0.5);border-radius:50%;pointer-events:none;z-index:9998;transform:translate(-50%,-50%);transition:width .25s,height .25s,border-color .25s,opacity .3s;will-change:left,top;';
      document.body.appendChild(ring);
      document.body.appendChild(dot);

      var mx = window.innerWidth / 2, my = window.innerHeight / 2, rx = mx, ry = my;
      document.addEventListener('mousemove', function (e) { mx = e.clientX; my = e.clientY; dot.style.left = mx + 'px'; dot.style.top = my + 'px'; });

      (function loop() {
        rx += (mx - rx) * 0.12; ry += (my - ry) * 0.12;
        ring.style.left = Math.round(rx) + 'px'; ring.style.top = Math.round(ry) + 'px';
        requestAnimationFrame(loop);
      })();

      document.addEventListener('mouseover', function (e) {
        if (e.target.closest('a,button,[onclick],.skill-card,.timeline-item,.edu-card')) {
          ring.style.width = '42px'; ring.style.height = '42px'; ring.style.borderColor = 'rgba(201,168,76,0.9)'; dot.style.opacity = '0';
        }
      });
      document.addEventListener('mouseout', function (e) {
        if (e.target.closest('a,button,[onclick],.skill-card,.timeline-item,.edu-card')) {
          ring.style.width = '28px'; ring.style.height = '28px'; ring.style.borderColor = 'rgba(201,168,76,0.5)'; dot.style.opacity = '1';
        }
      });

      if ('ontouchstart' in window) { dot.style.display = 'none'; ring.style.display = 'none'; }
    })();

    /* CONTACT LINKS TOGGLE */
    function toggleConLinks(btn) {
      var box = document.getElementById('con-links-box');
      var isHidden = box.classList.contains('con-links-hidden');

      if (isHidden) {
        box.classList.remove('con-links-hidden');
        box.classList.add('con-links-visible');
        btn.textContent = isAr ? 'إخفاء' : 'Hide';
      } else {
        box.classList.remove('con-links-visible');
        box.classList.add('con-links-hidden');
        btn.textContent = isAr ? 'تواصل معي' : 'Contact Me';
      }
    }

    /* CONTACT FORM WITH EMAILJS */
    function submitContactForm() {
      var nameEl = document.getElementById('cf-name');
      var emailEl = document.getElementById('cf-email');
      var subjectEl = document.getElementById('cf-subject');
      var msgEl = document.getElementById('cf-message');

      var name = nameEl.value.trim();
      var email = emailEl.value.trim();
      var subject = subjectEl.value.trim();
      var msg = msgEl.value.trim();
      var successMsg = document.getElementById('cf-success');
      var submitBtn = document.querySelector('.cf-btn-primary');

      if (!name || !email || !msg) {
        alert(isAr ? 'يرجى ملء الحقول المطلوبة' : 'Please fill in all required fields');
        return;
      }

      if (typeof emailjs === 'undefined') {
        alert(isAr ? 'تعذر تحميل خدمة الإرسال، برجاء المحاولة لاحقًا أو التواصل عبر البريد الإلكتروني مباشرة.' : 'The messaging service failed to load. Please try again later or email directly.');
        return;
      }

      submitBtn.textContent = isAr ? 'جاري الإرسال...' : 'Sending...';
      submitBtn.disabled = true;

      var templateParams = {
        name: name,
        message: "Email: " + email + "\nSubject: " + (subject || 'Portfolio Inquiry') + "\n\nContent:\n" + msg,
        time: new Date().toLocaleString(isAr ? 'ar-EG' : 'en-US')
      };

      emailjs.send('service_rosiml7', 'template_z0pn5jd', templateParams)
        .then(function (response) {
          successMsg.style.display = 'block';
          submitBtn.textContent = isAr ? 'تم الإرسال ✓' : 'Sent ✓';

          // Clear fields
          nameEl.value = '';
          emailEl.value = '';
          subjectEl.value = '';
          msgEl.value = '';

          setTimeout(() => {
            successMsg.style.display = 'none';
            submitBtn.disabled = false;
            submitBtn.textContent = isAr ? 'إرسال الرسالة' : 'Send Message';
          }, 5000);
        }, function (error) {
          console.error('EmailJS Error:', error);
          alert(isAr ? 'حدث خطأ أثناء الإرسال' : 'Failed to send message');
          submitBtn.disabled = false;
          submitBtn.textContent = isAr ? 'إرسال الرسالة' : 'Send Message';
        });
    }

    /* DOWNLOAD — CV embedded as base64 so it always works, with no dependency on an external file */
    var CV_BASE64 = "";
    function dlPage() {
      var a = document.createElement("a");
      a.href = "data:application/pdf;base64," + CV_BASE64;
      a.download = "Ahmed Mahmoud Abdelkader C.V.pdf";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }